<script lang="ts">
  import {onMount} from 'svelte';
  import {call} from '../lib/api';
  import {t} from '../lib/i18n';
  import {parseDialogueSettings,parseDialoguePolicy,estimatedRate,rateText,type DialogueSettings,type DialoguePolicy} from '../lib/social-dialogue-settings';
  let {botId,disabled=false,onDirtyChange,onBusyChange}:{botId:string;disabled?:boolean;onDirtyChange?:(dirty:boolean)=>void;onBusyChange?:(busy:boolean)=>void}=$props();
  let baseline=$state<DialogueSettings>(),draft=$state<DialoguePolicy>(),rate=$state(''),pending=$state(false),error=$state('');let alive=false,epoch=0;
  const dirty=$derived(!!baseline&&!!draft&&(JSON.stringify(baseline.policy)!==JSON.stringify(draft)||rate!==rateText(baseline.policy.estimatedMicrosPerMillion)));
  $effect(()=>onDirtyChange?.(dirty));$effect(()=>onBusyChange?.(pending));
  async function refresh(){const id=botId,token=++epoch;try{const next=parseDialogueSettings(await call('get_social_snapshot',{botId:id}),id);if(alive&&id===botId&&token===epoch){baseline=next;draft=structuredClone(next.policy);rate=rateText(next.policy.estimatedMicrosPerMillion);error='';}}catch{if(alive&&id===botId)error='Die Dialogregeln sind derzeit nicht verfügbar.';}}
  export function discardDraft(){if(baseline){draft=structuredClone(baseline.policy);rate=rateText(baseline.policy.estimatedMicrosPerMillion);}}
  export async function saveDraft(){if(!draft||!baseline||pending||disabled)return;const id=botId,revision=baseline.revision,token=++epoch;pending=true;error='';try{const policy=parseDialoguePolicy({...draft,estimatedMicrosPerMillion:estimatedRate(rate)});const next=parseDialogueSettings(await call('set_social_dialogue_policy',{botId:id,expectedRevision:revision,policy}),id);if(next.revision!==revision+1)throw Error('dialogue_invalid');if(alive&&id===botId&&token===epoch){baseline=next;draft=structuredClone(next.policy);rate=rateText(next.policy.estimatedMicrosPerMillion);}}catch{if(alive&&id===botId)error='Die Dialogregeln wurden nicht bestätigt. Prüfe die Werte und lade neu.';}finally{if(alive)pending=false;}}
  onMount(()=>{alive=true;void refresh();return()=>{alive=false;++epoch;onDirtyChange?.(false);onBusyChange?.(false);};});
</script>
<details class="dialogue"><summary>{$t('Kurze Gespräche zwischen Figuren')}</summary><p class="note">{$t('Lokale Reaktionen sind der Standard. Modellgestützte Gespräche brauchen diese eigene Freigabe und weiterhin alle bestehenden Modell-, Ausgabe- und Budgetrechte. Fokus und Leise bleiben still.')}</p>{#if error}<p class="error" role="alert">{$t(error)}</p>{/if}{#if draft&&baseline}<fieldset disabled={pending||disabled}><label class="check"><input type="checkbox" bind:checked={draft.modelEnabled}/>{$t('Begrenzte Modellgespräche ausdrücklich erlauben')}</label><div class="fields"><label>{$t('Höchstens Gesprächsbeiträge')}<input type="number" min="1" max="4" step="1" bind:value={draft.maxTurns}/></label><label>{$t('Maximale Gesprächsdauer')}<select bind:value={draft.durationMs}><option value={10000}>{$t('10 Sekunden')}</option><option value={30000}>{$t('30 Sekunden')}</option><option value={60000}>{$t('1 Minute')}</option>{#if ![10000,30000,60000].includes(draft.durationMs)}<option value={draft.durationMs}>{draft.durationMs/1000} s</option>{/if}</select></label><label>{$t('Geschätzter USD-Preis je Million Token')}<input type="text" inputmode="decimal" bind:value={rate} placeholder="3.00"/></label></div><p class="note">{$t('Deine Preisangabe ist eine Planungsschätzung, keine Rechnungsgarantie. Ohne bekannten Tokenrahmen oder Preis bleiben nur lokale Reaktionen.')}</p><details><summary>{$t('Dialoggrenzen im Detail')}</summary><div class="fields"><label>{$t('Token je Gespräch')}<input type="number" min="0" max="1000000" step="1" bind:value={draft.tokenLimit}/></label><label>{$t('Token pro Tag')}<input type="number" min="0" max="10000000" step="1" bind:value={draft.dailyTokenLimit}/></label><label>{$t('Geschätzte Mikro-USD je Gespräch')}<input type="number" min="0" max="1000000" step="1" bind:value={draft.costLimitMicros}/></label><label>{$t('Geschätzte Mikro-USD pro Tag')}<input type="number" min="0" max="10000000" step="1" bind:value={draft.dailyCostLimitMicros}/></label><label>{$t('Gesprächspause in Millisekunden')}<input type="number" min="1000" max="3600000" step="1" bind:value={draft.cooldownMs}/></label></div></details></fieldset><button class="button primary" disabled={!dirty||pending||disabled} onclick={saveDraft}>{$t('Dialogregeln speichern')}</button>{/if}</details>
<style>.dialogue{border-top:1px solid var(--line);padding:16px 0}summary{font-size:12px;cursor:pointer}.note{font-size:12px;color:var(--muted);line-height:1.7}.error{font-size:12px;color:var(--danger)}fieldset{border:0;padding:0;margin:0}.check{display:flex;align-items:center;gap:8px;font-size:12px}.check input{width:auto;accent-color:var(--accent)}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.fields label{font-size:11px;display:grid;gap:8px}.dialogue :global(.dialogue){margin:16px 0}@media(max-width:680px){.fields{grid-template-columns:1fr}}</style>
